INSERT INTO "Module" ("id", "moduleNumber", "code", "name", "fullName", "purpose", "description", "credits", "notionalHours", "classroomHours", "workplaceHours", "order", "status", "createdAt", "updatedAt") VALUES ('4047d037-5805-44ec-ad21-743db53bdaaf', 1, 'NVC-M1', 'Use Basic Mathematics in Order to Fulfil New Venture Functions Effectively', 'Module 1: Numeracy for New Ventures', 'Equip learners with mathematical skills for business', 'This learning programme aims to equip learners with the necessary mathematical skills and knowledge to successfully run their own businesses.', 16, 160, 48, 112, 1, 'ACTIVE', 1771278792286, 1771309328220);
INSERT INTO "Module" ("id", "moduleNumber", "code", "name", "fullName", "purpose", "description", "credits", "notionalHours", "classroomHours", "workplaceHours", "order", "status", "createdAt", "updatedAt") VALUES ('ce6d850b-a229-4e96-aa11-acc250df0f1d', 2, 'NVC-M2', 'HIV/AIDS & Communications', 'Module 2: HIV/AIDS & Communications', 'Equip learners with communication skills and HIV/AIDS awareness for business interaction', 'This module equips learners with the necessary communication skills and HIV/AIDS knowledge to successfully interact with employees, clients and suppliers.', 24, 240, 72, 168, 2, 'ACTIVE', 1771278792374, 1771309328285);
INSERT INTO "Module" ("id", "moduleNumber", "code", "name", "fullName", "purpose", "description", "credits", "notionalHours", "classroomHours", "workplaceHours", "order", "status", "createdAt", "updatedAt") VALUES ('87673d4f-8cb9-40d5-aa14-95e5f136cae8', 3, 'NVC-M3', 'Determine market requirements and manage the relevant marketing and selling processes', 'Module 3: Marketing and Selling for New Ventures', 'Equip learners with knowledge of market requirements and marketing strategies', 'This module equips learners with knowledge of market requirements and how to benefit from this knowledge in the form of increased sales.', 22, 220, 66, 154, 3, 'ACTIVE', 1771278792430, 1771309328336);
INSERT INTO "Module" ("id", "moduleNumber", "code", "name", "fullName", "purpose", "description", "credits", "notionalHours", "classroomHours", "workplaceHours", "order", "status", "createdAt", "updatedAt") VALUES ('91918289-ce56-4c9e-b98f-2cd6840666ae', 4, 'NVC-M4', 'Demonstrate an understanding of the sector/industry in which the business operates', 'Module 4: Business Sector & Industry', 'Equip learners with skills for procurement, tendering, and legal compliance', 'This module provides learners with knowledge and skills to procure raw material, tender for business, administer contracts, and comply with legal and health & safety requirements.', 26, 260, 78, 182, 4, 'ACTIVE', 1771278792483, 1771309328406);
